def calculate_D(b):
    # D = 2^(2b+2) - 2^(b+2) + 1 - 8 * 3^b
    D = (2**(2*b + 2)) - (2**(b + 2)) + 1 - (8 * (3**b))
    return D

for b in range(1, 6):
    D_val = calculate_D(b)
    print(f"b={b}: D = {D_val}")
    import math
    if D_val >= 0:
        sqrt_D = math.isqrt(D_val)
        if sqrt_D * sqrt_D == D_val:
            print(f"b={b}: D is a perfect square (sqrt={sqrt_D})")
        else:
            print(f"b={b}: D is not a perfect square")
